require 'json';require 'digest';require 'fileutils';require 'open3';require_relative '../../scripts/lib/consumer-sanitizers';require_relative 'leak-set'
repo,s,out=ARGV;raise 'fresh remaining audit' if File.exist?(out);FileUtils.mkdir_p(out+'/tmp');File.write(out+'/not-dir','x');baseline=JSON.parse(File.read(s+'/m3-sanitizer-baseline-01/allocation-audit.json')).fetch('baseline');allowed=baseline.fetch('allocations').map{|r|JSON.generate(r)}.tally;map=ProducerLeakSet.added_lines(repo+'/patches/M4-typing-probe.patch');rows=[];tool=s+'/asan-build-01/bin/spinel'
[['child-failure',s+'/failure-controls-03/refused.rb',{},'typing probe before analysis failed'],['temp-failure',s+'/transport-controls-01/small.rb',{'TMPDIR'=>out+'/not-dir'},'typing probe stderr temp failed']].each do |name,source,extra,message|
 argv=['/usr/bin/timeout','--kill-after=5s','60s',tool,'--emit-mlir='+out+'/'+name+'.mlir','--analysis-root=target:obj_Seed','--emit-typing-probe',source];env=ConsumerSanitizers.environment.merge('TMPDIR'=>out+'/tmp').merge(extra);o,e,st=Open3.capture3(env,*argv,unsetenv_others:true,rlimit_core:0);File.write(out+'/'+name+'.stdout',o);File.write(out+'/'+name+'.stderr',e);reports=ConsumerSanitizers.classify(e);leaks=ProducerLeakSet.parse(e,s+'/asan-build-01',map);set=JSON.parse(JSON.generate(leaks.fetch(:allocations))).map{|r|JSON.generate(r)}.tally;additional=set.reject{|key,count|count<=allowed.fetch(key,0)};row={name:name,argv:argv,environment:env,rc:st.exitstatus,signal:st.termsig,reports:reports,existing_leaks:leaks,additional_allocations:additional};rows<<row;File.write(out+'/ledger.json',JSON.pretty_generate(rows)+"\n");raise 'STOP new sanitizer allocation '+name unless additional.empty?;raise 'STOP non-leak sanitizer '+name unless reports.all?{|r|r.fetch('family')=='LeakSanitizer'};expected=leaks.fetch(:objects)>0 ? 87 : 1;raise 'STOP failure status '+name unless st.exitstatus==expected&&!st.termsig&&o.empty?&&e.include?(message)&&!File.exist?(out+'/'+name+'.mlir')
